/* 跨来源只读聚合；每次刷新重新读取，不维护另一套待办状态。 */
(function(r){const node=typeof module==='object'&&module.exports,D=node?require('./workbench-data.js'):r.EAM_WORKBENCH_JSON;
function createApi(o){return {async request(method,path){
 const ctx=o.context(),actor=o.people.find(p=>p.id===ctx.person);if(method!=='GET'||path!=='/workbench')throw new Error('工作台仅支持查询');if(!actor?.roles.includes(ctx.role)||ctx.scenario==='forbidden')throw new Error('人员或角色无访问权限');
 const equipment=o.equipment(),scope=new Set(ctx.equipmentIds||equipment.map(e=>e.id)),people=new Map(o.people.map(p=>[p.id,p.name])),items=[],errors=[];
 const own=id=>equipment.find(e=>e.id===id)?.ownerId===ctx.person,supervisor=['supervisor','engineer'].includes(ctx.role);
 const add=(source,row,group,target,query,owner,due,status,action)=>{if(!scope.has(row.equipmentId||'EQ-001'))return;items.push({id:source+':'+row.id+':'+group,source,sourceId:row.id,equipmentId:row.equipmentId||'EQ-001',equipment:equipment.find(e=>e.id===(row.equipmentId||'EQ-001'))?.name||row.equipmentId,title:row.name||row.description||row.scope||row.id,group,groupLabel:D.groups[group],ownerId:owner||'',owner:people.get(owner)||owner||'待安排',dueAt:due||'',status:D.states[status]||status,overdue:!!due&&Number.isFinite(Date.parse(due))&&Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(due)?due+'T23:59:59+08:00':due)<Date.now(),target,query,action});};
 const attempt=async(name,fn)=>{try{return await fn();}catch(e){errors.push({source:name,message:e.message});return null;}};
 const all=async kind=>{const rows=[];for(let page=1;;page++){const v=await o.maintenance.request('GET','/maintenance/'+kind+'?page='+page+'&pageSize=50');rows.push(...v.items);if(rows.length>=v.total)return rows;}};
 const [inspection,tasks,config,problem]=await Promise.all([attempt('点检',()=>o.inspection.request('GET','/inspection/tasks')),attempt('保养',()=>all('tasks')),attempt('保养配置',()=>o.maintenance.request('GET','/maintenance/config')),attempt('异常与维修',async()=>{const kinds=['discoveries','defects','failures','hazards','work-orders'];return Promise.all(kinds.map(async kind=>({kind,...await o.problem.request('GET','/'+kind)})));})]);
 for(const t of inspection?.items||[])if(t.assignee===ctx.person&&!['complete','cancelled'].includes(t.status))add('点检',t,t.returnReason?'rework':'execute','inspection',t.type==='special'?{check:t.id,tab:'special'}:{task:t.id},t.assignee,t.windowEnd||(t.window?(/^\d{4}-\d{2}-\d{2}/.test(t.window.split('—').at(-1))?t.window.split('—').at(-1):t.window.slice(0,10)+' '+t.window.split('—').at(-1)):''),'pending','执行点检');
 for(const t of tasks||[]){const query={id:t.id,equipment:t.equipmentId},person=t.primaryPersonId;
 if(['ready','in_progress','paused'].includes(t.status)&&!t.termination?.status?.includes('pending')&&[person,...t.collaboratorIds].includes(ctx.person))add('保养',t,t.returnReason?'rework':'execute','maintenance-task',query,person,t.windowEnd,t.status,'处理任务');
 if(t.status==='pending_assignment'&&t.actions.assign)add('保养',t,'dispatch','maintenance-task',query,'',t.windowEnd,t.status,'派工');
 if(supervisor&&t.overdue&&!['completed','cancelled','terminated'].includes(t.status))add('保养',t,'overdue','maintenance-task',query,person,t.windowEnd,t.status,'跟踪逾期');
 if(t.actions.acceptance)add('保养',t,'review','maintenance-task',query,person,t.windowEnd,t.status,'独立验收');
 if(t.termination?.applyStatus==='blocked'&&(supervisor||own(t.equipmentId)||t.termination.requestedBy===ctx.person))add('保养',t,'termination','maintenance-task',query,t.termination.requestedBy,t.termination.followupDueAt,'业务待处理','更正终止申请');
 if(t.actions['apply-early-start-result'])add('保养',t,'review','maintenance-task',query,t.earlyStart.requestedBy,t.earlyStart.effectiveUntil,'pending_review','获取提前开工审批结果');
 if(t.actions['review-termination'])add('保养',t,'termination','maintenance-task',query,t.termination.requestedBy,t.termination.followupDueAt,'pending_review','获取外部审批结果');
 if(t.followup&&t.followup.status!=='completed'&&(t.followup.ownerId===ctx.person||supervisor||own(t.equipmentId))){add('保养后续',t,'followup','maintenance-task',query,t.followup.ownerId,t.followup.dueAt,t.followup.status,t.actions['submit-followup']?'提交后续结果':t.actions['review-followup']?'复核后续结果':'查看安排');}
 }
 for(const response of problem||[])for(const p of response.rows||[]){if(['closed','cancelled','archived','withdrawn','draft'].includes(p.status)&&p.restriction?.status!=='active')continue;const kind=response.kind;
 if(kind==='work-orders'){const q={order:p.id,equipment:p.equipmentId};if(['pending','approved'].includes(p.terminationApproval?.status)){if(supervisor||own(p.equipmentId))add('维修',p,'termination','order',q,p.terminationApproval.submittedBy,p.dueAt,p.terminationApproval.status==='pending'?'pending_review':'业务待处理','查看外部审批结果');continue;}if(p.assigneeId===ctx.person&&['assigned','executing','paused'].includes(p.status))add('维修',p,p.reworkRequired?'rework':'execute','order',q,p.assigneeId,p.dueAt,p.status,'处理工单');if(supervisor&&['approved','draft','pending_approval'].includes(p.status))add('维修',p,'dispatch','order',q,p.assigneeId,p.dueAt,p.status,'处理派工');if(supervisor&&p.dueAt&&Date.parse(p.dueAt+'T23:59:59+08:00')<Date.now()&&!['closed','cancelled'].includes(p.status))add('维修',p,'overdue','order',q,p.assigneeId,p.dueAt,p.status,'跟踪逾期');if(supervisor&&p.status==='technical_complete'&&p.assigneeId!==ctx.person)add('维修',p,'review','acceptance',q,p.assigneeId,p.dueAt,p.status,'独立验收');if((own(p.equipmentId)||supervisor)&&p.status==='accepted')add('维修',p,'problem','order',q,p.assigneeId,p.dueAt,p.status,'业务关闭');continue;}
 const target={discoveries:'abnormal-events',defects:'defect-list',failures:'failure-events',hazards:'hazards'}[kind];if(p.ownerId===ctx.person||supervisor||own(p.equipmentId)||(kind==='hazards'&&ctx.role==='safety'))add(kind==='discoveries'?'异常':kind==='hazards'?'隐患':kind==='defects'?'缺陷':'故障',p,'problem',target,{id:p.id,equipment:p.equipmentId,...(kind==='discoveries'&&p.status==='submitted'&&supervisor?{action:'triage'}:{})},p.ownerId,p.dueAt,p.status,'处理问题');
 if(p.restriction?.status==='active'&&(own(p.equipmentId)||ctx.role==='safety'||supervisor))add('设备限制',p,'restriction',target,{id:p.id,equipment:p.equipmentId},p.ownerId,p.controlValidUntil||p.dueAt,'限制生效','查看限制');
 }
 const unique=[...new Map(items.map(x=>[x.id,x])).values()].sort((a,b)=>Number(b.overdue)-Number(a.overdue)||(a.dueAt||'9999').localeCompare(b.dueAt||'9999')||a.id.localeCompare(b.id));return {items:unique,groups:D.groups,metrics:{pending:unique.filter(x=>['execute','rework','dispatch'].includes(x.group)).length,review:unique.filter(x=>['review','termination'].includes(x.group)).length,overdue:unique.filter(x=>x.overdue).length,unclosed:unique.filter(x=>['problem','followup','restriction'].includes(x.group)).length},errors,dataAsOf:new Date().toISOString(),asOfDate:config?.asOfDate};
}};}
const api={createApi};if(node)module.exports=api;else r.EamWorkbenchApi=createApi({context:()=>r.Eam.s,people:r.EamDomain.people,equipment:()=>r.Eam.s.equipmentRecords,inspection:{async request(){await new Promise(done=>setTimeout(done,80));const s=r.Eam.s;return {items:[s.task,...s.taskInstances,...s.checks.map(c=>({...c,type:'special'}))].map(t=>({...t,equipmentId:t.equipmentId||'EQ-001'}))};}},maintenance:r.EamMaintenanceApi,problem:r.EamProblemApi});
})(typeof window==='undefined'?globalThis:window);
